using System;
using System.Collections.Generic;
using Faolan.Core.Network.Codecs.World;
using Xunit;

namespace Faolan.Tests
{
	// Byte-exact for the CoreClaimIIR claim list (0x06EC1255, sub 0x0001) - what the server sends when the client
	// opens the Claims/Redeem window (docs/subsystems/item-claims.md). Oracle: the NecroL80 login_redeem-claim capture,
	// frame 399 (handle 0x0802E5D4), 19 rows of 106 bytes. Each row's 16-byte token and the constant 8-byte batch
	// guid (b290805c29e627ca) are display-only opaque handles fed in verbatim, so reconstructing the row set from the
	// captured tuples reproduces the packet exactly. Guards the wire layout so a refactor can't silently drift it.
	public class CoreClaimListCodecTests
	{
		private const uint Handle = 0x0802E5D4;
		private const string BatchGuidHex = "b290805c29e627ca";

		// (index, template, LEVEL, code, tokenHex, type, QUANTITY) exactly as captured, in wire order. The u64 is the
		// item level (not stack count); quantity is the mirrored tail pair (0 for the single-item claims, 20 for the
		// one type-4 account-currency row). See ClaimEntry.
		private static readonly (uint Index, uint Tpl, ulong Level, string Code, string Token, uint Type, uint Quantity)[] Captured =
		{
			(1, 4621781, 80, "9CP4", "f8f2753b3f1995b4ada92fdf16173fd1", 6, 0),
			(2, 4592970, 1, "M3B2", "156a418124721065e15a4393f84ad05a", 6, 0),
			(3, 4208449, 5, "UXAM", "840512e6d1bafaba5cf7cbb34c13eb21", 6, 0),
			(4, 3765539, 1, "OS6I", "afcdca277b2c9e5fd21c913e0023080f", 6, 0),
			(5, 4208450, 5, "BYN6", "2ba8af239d9975aa118016765f02eba1", 6, 0),
			(6, 4208485, 5, "NAPQ", "5d58d1d57e8d2e7ef44d00f8b51a76d3", 6, 0),
			(7, 4208476, 5, "EXYR", "2939be7ac99abf70ff3bd41f2c19b637", 6, 0),
			(8, 4208486, 5, "A8VK", "ce4797d3163cfadc7955e79c1f21abfc", 6, 0),
			(9, 3800274, 40, "CGFP", "c23131135fdbbf5426b2b5a85244b4fe", 6, 0),
			(10, 3535016, 5, "X26T", "f7827de5d47f87c43db7abf3c15e4f05", 6, 0),
			(11, 3857326, 1, "TWBT", "202dac83bd46ca7b385c3b81ed29ab93", 6, 0),
			(12, 3765547, 1, "QHNT", "97a5c7944e47accd2a7c497363523d03", 6, 0),
			(13, 3951828, 1, "L80R", "6e101da88d2e2ed63f265eb30e9945aa", 6, 0),
			(14, 3663583, 1, "VN68", "af095c952097fcba63ee82642c6dd722", 6, 0),
			(15, 318951, 1, "602V", "903bc6dc788053fc1b1e1b0285a62e89", 6, 0),
			(16, 3535303, 19, "CU2E", "d632a37ae44055dd465df6f420ae35fc", 6, 0),
			(17, 3514741, 5, "JBUE", "dd6127476954f064fd21008903f001cd", 6, 0),
			(18, 4208484, 5, "VPU5", "6a41f5e76497f325ecacbb54a6254252", 6, 0),
			(19, 4552866, 1, "RQIL", "ed414c09b038fa793b7085ead7de9b92", 4, 20),
		};

		// frame 399 inner IIR body (the captured packet minus its leading u32 length prefix 0x000007F0).
		private const string CapturedBody =
			"";

		[Fact]
		public void Build_MatchesCapturedList()
		{
			var guid = Convert.FromHexString(BatchGuidHex);
			var claims = new List<ClaimEntry>();
			foreach (var c in Captured)
				// In the initial list, remaining == max, so Quantity and MaxQuantity are the same captured word.
				claims.Add(new ClaimEntry(c.Index, c.Tpl, c.Level, c.Code, Convert.FromHexString(c.Token), guid, c.Type, c.Quantity, c.Quantity));

			var actual = Convert.ToHexString(CoreClaimListCodec.Build(Handle, claims)).ToLowerInvariant();
			Assert.Equal(CapturedBody, actual);
		}

		// The sub-0x05 multi-charge redeem ack (…use-double-xp-potion capture, frame 396): after redeeming the Double
		// XP row (index 19, type 4) once, the server echoes the single entry with remaining 19 / max 20.
		private const string CapturedAck =
			"06ec12550000c3500802e5d4000500000013004578a2004578a200000000000000015251494ced414c09b038fa793b7085ead7de9b92ed414c09b038fa793b7085ead7de9b92b290805c29e627cab290805c29e627ca00000004000000130000001400000000000000000000000000000001000000000000";

		[Fact]
		public void BuildRedeemAck_MatchesCapture()
		{
			var entry = new ClaimEntry(19, 4552866, 1, "RQIL", Convert.FromHexString("ed414c09b038fa793b7085ead7de9b92"),
				Convert.FromHexString(BatchGuidHex), Type: 4, Quantity: 19, MaxQuantity: 20);

			var actual = Convert.ToHexString(CoreClaimListCodec.BuildRedeemAck(Handle, entry)).ToLowerInvariant();
			Assert.Equal(CapturedAck, actual);
		}
	}
}
